package infra;

import domain.FxQuote;

import java.io.IOException;
import java.io.InputStream;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

/** Thin wrapper around the vendor quote CLI. One process per call. */
public class FxqClient {
    private final Path bin;
    private final long timeoutSeconds;

    public FxqClient(Path bin, long timeoutSeconds) {
        this.bin = bin;
        this.timeoutSeconds = timeoutSeconds;
    }

    /** Raw stdout line for {@code fxq rate PAIR DATE}. */
    public String rate(String pair, LocalDate date) {
        List<String> cmd = new ArrayList<>();
        cmd.add(bin.toString());
        cmd.add("rate");
        cmd.add(pair);
        cmd.add(date.toString());
        return run(cmd);
    }

    /** Parses one quote line: {@code PAIR YYYY-MM-DD RATE ...}. */
    public static FxQuote parse(String line) {
        String[] t = line.trim().split("\\s+");
        if (t.length < 3) {
            throw new IllegalArgumentException("unexpected quote line: " + line);
        }
        return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]));
    }

    private String run(List<String> cmd) {
        try {
            Process p = new ProcessBuilder(cmd).start();
            byte[] out;
            byte[] err;
            try (InputStream o = p.getInputStream(); InputStream e = p.getErrorStream()) {
                out = o.readAllBytes();
                err = e.readAllBytes();
            }
            if (!p.waitFor(timeoutSeconds, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new FxqException("timeout", cmd);
            }
            if (p.exitValue() != 0) {
                throw new FxqException(new String(err, StandardCharsets.UTF_8).trim(), cmd);
            }
            String line = new String(out, StandardCharsets.UTF_8).trim();
            if (line.isEmpty()) throw new FxqException("empty output", cmd);
            return line;
        } catch (IOException e) {
            throw new FxqException("exec failed: " + e.getMessage(), cmd);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new FxqException("interrupted", cmd);
        }
    }

    public static class FxqException extends RuntimeException {
        public FxqException(String code, List<String> cmd) {
            super("fxq failed [" + code + "]: " + String.join(" ", cmd));
        }
    }
}
---RATE---
package service;

import domain.FxQuote;
import infra.FxqClient;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** FX rates for settlement and display, backed by the vendor CLI with a per-run cache. */
public class RateService {
    private final FxqClient client;
    private final Map<String, FxQuote> cache = new HashMap<>();
    private int vendorCalls;

    public RateService(FxqClient client) {
        this.client = client;
    }

    public FxQuote quote(String currency, LocalDate date) {
        String pair = CurrencyPairs.pairOf(currency);
        return cache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            return FxqClient.parse(client.rate(pair, date));
        });
    }

    /** Rate applied to card transactions of the given KST settlement date. */
    public BigDecimal settlementRate(String currency, LocalDate date) {
        return quote(currency, date).rate();
    }

    public int vendorCalls() {
        return vendorCalls;
    }
}
---SETTLE---
package service;

import domain.DailyLine;
import domain.Partner;
import domain.Transaction;
import infra.DataFiles;
import util.Money;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Builds per-partner daily settlement lines from the transaction feed. */
public class SettlementService {
    private final DataFiles data;
    private final RateService rates;
    private final BusinessDateResolver dates;

    public SettlementService(DataFiles data, RateService rates, BusinessDateResolver dates) {
        this.data = data;
        this.rates = rates;
        this.dates = dates;
    }

    public List<DailyLine> settle(LocalDate from, LocalDate to) {
        Map<String, long[]> acc = new TreeMap<>(); // key "date|partner" -> {count, grossKrw}
        for (Transaction t : data.transactions()) {
            LocalDate d = dates.dateOf(t.approvedAt());
            if (d.isBefore(from) || d.isAfter(to)) continue;
            Partner p = data.partner(t.partnerId()).orElse(null);
            if (p == null || !p.active()) continue;
            long krw = convert(t, d);
            long[] a = acc.computeIfAbsent(d + "|" + p.id(), k -> new long[2]);
            a[0]++;
            a[1] += krw;
        }
        List<DailyLine> out = new ArrayList<>();
        for (var e : acc.entrySet()) {
            String[] k = e.getKey().split("\\|");
            Partner p = data.partner(k[1]).orElseThrow();
            long gross = e.getValue()[1];
            out.add(new DailyLine(LocalDate.parse(k[0]), p.id(), (int) e.getValue()[0], gross,
                    Money.fee(gross, p.feeBps())));
        }
        return out;
    }

    private long convert(Transaction t, LocalDate businessDate) {
        var rate = rates.settlementRate(t.currency(), businessDate);
        return Money.toKrw(t.signedAmount(), rate, CurrencyPairs.unitOf(t.currency()));
    }
}
---BOARD---
package service;

import domain.FxQuote;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/** Customer-facing exchange rate board for the app's travel wallet screen. */
public class RateBoardService {
    private final RateService rates;
    private final List<String> currencies;

    public RateBoardService(RateService rates, List<String> currencies) {
        this.rates = rates;
        this.currencies = currencies;
    }

    public List<FxQuote> board(LocalDate date) {
        List<FxQuote> out = new ArrayList<>();
        for (String c : currencies) {
            if (CurrencyPairs.supported(c)) out.add(rates.quote(c, date));
        }
        return out;
    }
}
