    String[] t = line.trim().split("\\s+");
    if (t.length < 3) {
        throw new IllegalArgumentException("unexpected quote line: " + line);
    }
    boolean carried = t.length > 3 && t[3].startsWith("~");
    return new FxQuote(t[0], LocalDate.parse(t[1]), new BigDecimal(t[2]), carried);
}

